from base.exceptions import EntityBadRequestErrorfrom entities import Container, ContainerType as ctfrom services.container import ContainerServicefrom services.join_request import JoinRequestServicefrom services.subscribe import SubscribeServicefrom sqlalchemy.ext.asyncio import AsyncSessionchannels = [    ct.PUBLIC_CHANNEL,    ct.PRIVATE_CHANEL]class PublicChannelService(ContainerService):    def __init__(self, session: AsyncSession):        super().__init__(session)        self.subs_service = SubscribeService(session)    async def subscribe(self, user_id: int, channel_id: int):        await self.subs_service.create_subscribe(user_id=user_id, container_id=channel_id)class PrivateChannelService(ContainerService):    def __init__(self, session: AsyncSession):        super().__init__(session)        self.jr_service = JoinRequestService(session)        self.subs_service = SubscribeService(session)    async def send_jr(self, user_id: int, channel_id: int):        await self.subs_service.check_already_exists(user_id=user_id, container_id=channel_id)        await self.jr_service.send_jr(user_id=user_id, channel_id=channel_id)    async def process_jr(            self, user_id: int,            jr_id: int, approve: bool    ):        jr = await self.jr_service.get_item_by_id(jr_id)        channel = await self.get_item_by_id(jr.container_id)        if channel.author_id != user_id:            raise EntityBadRequestError("Недостаточно прав")        if approve:            await self.subs_service.create_subscribe(                user_id=user_id, container_id=jr.container_id            )        await self.jr_service.delete_item_by_id(jr.id)    async def get_jrs(self, user_id: int, channel: Container, ):        if user_id != channel.author_id:            raise EntityBadRequestError("Недостаточно прав")        return await self.jr_service.get_jrs(            channel_id=channel.id,        )